  }

  @protected
  void sse_encode_waiting_row(WaitingRow self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_inbox_row(self.row, serializer);
    sse_encode_list_String(self.to, serializer);
    sse_encode_opt_box_autoadd_i_64(self.remindAt, serializer);
  }
}
